  function place(ev){
    var r=svg.getBoundingClientRect();
    var x=ev.clientX-r.left+12,y=ev.clientY-r.top-10;
    if(x+tip.offsetWidth>r.width) x=ev.clientX-r.left-12-tip.offsetWidth;
